79	    private Set<Pet> pets;
80	
81	    public String getAddress() {
82	        return this.address;
83	    }
84	
85	    public void setAddress(String address) {
86	        this.address = address;
87	    }
88	
89	    public String getCity() {
90	        return this.city;
91	    }
92	
93	    public void setCity(String city) {
94	        this.city = city;
95	    }
96	
97	    public String getTelephone() {
98	        return this.telephone;
99	    }
100	
101	    public void setTelephone(String telephone) {
102	        this.telephone = telephone;
103	    }
104	
105	    public String getEmail() {
106	        return this.email;
107	    }
108	
109	    public void setEmail(String email) {
110	        this.email = email;
111	    }
112	
113	    public String getPostcode() {
114	        return this.postcode;
115	    }
116	
117	    public void setPostcode(String postcode) {
118	        this.postcode = postcode;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    /**
138	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where
139	     * {@code YY} is the last two digits of the {@code registrationDate} year, e.g.
140	     * {@code "NSW-1A2B3C4D-M26"}. Derived from the owner's own fields; {@code null} until
141	     * both the customer code and registration date have been assigned.
142	     */
143	    @Transient
144	    public String getMembershipNumber() {
145	        if (this.customerCode == null || this.registrationDate == null) {
146	            return null;
147	        }
148	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
149	    }
150	
151	    /**
152	     * The owner's check digit: a single {@link Luhn} check digit computed over the digits
153	     * of the owner's {@link #customerCode}. {@code null} until the customer code has been
154	     * assigned.
155	     */
156	    @Transient
157	    public Integer getCheckDigit() {
158	        if (this.customerCode == null) {
159	            return null;
160	        }
161	        return Luhn.checkDigit(this.customerCode);
162	    }
163	
164	    /**
165	     * The owner's region: the canonical region derived from the owner's {@link #postcode}
166	     * via the fixed {@link RegionPostcodeTable}, falling back to the owner's {@link #city}
167	     * via the fixed {@link CityRegionTable} when the postcode is absent or in no known
168	     * range, or {@code "UNKNOWN"} when neither yields a region. This is the {@code REGION}
169	     * segment of the owner's {@link #getCustomerCode() customer code}.
170	     */
171	    @Transient
172	    public String getRegion() {
173	        return RegionPostcodeTable.regionOf(this.postcode)
174	            .orElseGet(() -> CityRegionTable.regionOf(this.city));
175	    }
176	
177	    /**
178	     * The owner's locality, read from its region-and-hash identity: the {@code REGION}
179	     * segment (everything before the first {@code '-'}) of the owner's
180	     * {@link #getCustomerCode() customer code}. Falls back to the owner's live
181	     * {@link #getRegion() region} until a customer code has been assigned.
182	     */
183	    @Transient
184	    public String getLocality() {
185	        if (this.customerCode == null) {
186	            return getRegion();
187	        }
188	        int dash = this.customerCode.indexOf('-');
189	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
190	    }
191	
192	    /**
193	     * The owner's preferred contact channel, derived on read from the owner's own
194	     * fields: {@code "EMAIL"} when the owner has an email address, otherwise
195	     * {@code "PHONE"}.
196	     */
197	    @Transient
198	    public String getContactPreference() {
199	        return (this.email == null || this.email.isBlank()) ? "PHONE" : "EMAIL";
200	    }
201	
202	    /**
203	     * The owner's identity key: the single value used to detect duplicate owners on
204	     * create. It joins the owner's (already normalized) telephone, email and household id
205	     * with {@code '|'} — {@code <telephone>|<email>|<householdId>} — a missing email or
206	     * household id contributing an empty segment. Two owners are duplicates only when
207	     * their whole identity keys are equal.
208	     */
209	    @Transient
210	    public String getIdentityKey() {
211	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
212	    }
213	
214	    private static String orEmpty(String value) {
215	        return value == null ? "" : value;
216	    }
217	
218	    public String getHouseholdId() {
219	        return this.householdId;
220	    }
221	
222	    public void setHouseholdId(String householdId) {
223	        this.householdId = householdId;
224	    }
225	
226	    public Integer getNamesakeCount() {
227	        return this.namesakeCount;
228	    }
229	
230	    public void setNamesakeCount(Integer namesakeCount) {
231	        this.namesakeCount = namesakeCount;
232	    }
233	
234	    public Integer getHouseholdSize() {
235	        return this.householdSize;
236	    }
237	
238	    public void setHouseholdSize(Integer householdSize) {
239	        this.householdSize = householdSize;
240	    }
241	
242	    /**
243	     * The owner's membership level, a number assigned on create and never below 1.
244	     * Levels 1 to 3 are earned from the owner's own fields at creation time (see
245	     * {@code MembershipLevelAssigner}); level 4 is reserved for tenure.
246	     */
247	    public Integer getMembershipLevel() {
248	        return this.membershipLevel;
249	    }
250	
251	    public void setMembershipLevel(Integer membershipLevel) {
252	        this.membershipLevel = membershipLevel;
253	    }
254	
255	    public Boolean getBulkSignupWarning() {
256	        return this.bulkSignupWarning;
257	    }
258	
259	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
260	        this.bulkSignupWarning = bulkSignupWarning;
261	    }
262	
263	    protected Set<Pet> getPetsInternal() {
264	        if (this.pets == null) {
265	            this.pets = new HashSet<>();
266	        }
267	        return this.pets;
268	    }
269	
270	    protected void setPetsInternal(Set<Pet> pets) {
271	        this.pets = pets;
272	    }
273	
274	    public List<Pet> getPets() {
275	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
276	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
277	        return Collections.unmodifiableList(sortedPets);
278	    }
279	
280	    public void setPets(List<Pet> pets) {
281	        this.pets = new HashSet<>(pets);
282	    }
283	
284	    public void addPet(Pet pet) {
285	        getPetsInternal().add(pet);
286	        pet.setOwner(this);
287	    }
288	
289	    /**
290	     * Return the Pet with the given name, or null if none found for this Owner.
291	     *
292	     * @param name to test
293	     * @return true if pet name is already in use
294	     */
295	    public Pet getPet(String name) {
296	        return getPet(name, false);
297	    }
298	
299	    /**
300	     * Return the Pet with the given name, or null if none found for this Owner.
301	     *
302	     * @param name to test
303	     * @return true if pet name is already in use
304	     */
305	    public Pet getPet(String name, boolean ignoreNew) {
306	        name = name.toLowerCase();
307	        for (Pet pet : getPetsInternal()) {
308	            if (!ignoreNew || !pet.isNew()) {
309	                String compName = pet.getName();
310	                compName = compName.toLowerCase();
311	                if (compName.equals(name)) {
312	                    return pet;
313	                }
314	            }
315	        }
316	        return null;
317	    }
318	
319	    public Pet getPet(Integer petId) {
320	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
321	    }
322	
323	    @Override
324	    public String toString() {
325	        return new ToStringCreator(this)
326	
327	            .append("id", this.getId())
328	            .append("new", this.isNew())
329	            .append("lastName", this.getLastName())
330	            .append("firstName", this.getFirstName())
331	            .append("address", this.address)
332	            .append("city", this.city)
333	            .append("telephone", this.telephone)
334	            .append("email", this.email)
335	            .append("registrationDate", this.registrationDate)
336	            .append("customerCode", this.customerCode)
337	            .toString();
338	    }
